// Holds the recognized command line flags. All fields default to `false`.
#[derive(Debug, PartialEq, Default)]
pub struct DenoFlags {
  pub help: bool,
  pub log_debug: bool,
  pub version: bool,
  pub reload: bool,
  pub allow_write: bool,
  pub allow_net: bool,
}

// Parses the recognized flags out of the given argument list, mapping them to
// the fields of `DenoFlags`. Returns the parsed flags together with the
// arguments that were not recognized as flags (e.g. the script name and its
// arguments).
pub fn set_flags(args: Vec<String>) -> (DenoFlags, Vec<String>) {
  let mut flags = DenoFlags::default();
  let mut rest = Vec::<String>::new();

  for arg in args {
    match arg.as_str() {
      "-h" | "--help" => flags.help = true,
      "-D" | "--log-debug" => flags.log_debug = true,
      "-v" | "--version" => flags.version = true,
      "-r" | "--reload" => flags.reload = true,
      "--allow-write" => flags.allow_write = true,
      "--allow-net" => flags.allow_net = true,
      _ => rest.push(arg),
    }
  }

  (flags, rest)
}

